 "content": "from collections import deque


def transform(grid):
    """Recolor the smallest zero component 7 and largest zero component 8."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = x + dx, y + dy
                    if 0 <= a < h and 0 <= b < w and grid[a][b] == 0 and (a, b) not in seen:
                        seen.add((a, b))
                        q.append((a, b))
            components.append(cells)
    if components:
        smallest = min(components, key=len)
        largest = max(components, key=len)
        for r, c in smallest:
            out[r][c] = 7
        for r, c in largest:
            out[r][c] = 8
    return out
